  render: ({
    compositionName,
    swapSides
  }) => {
    const {
      dual,
      singlesDefinition,
      linesOf
    } = completedDual();
    const singles = linesOf(singlesDefinition.collectionId);
    [singles[1], singles[4]].forEach(unplayed);
    singles.filter((line: any) => line.orderOfFinish).sort((a: any, b: any) => a.orderOfFinish - b.orderOfFinish).forEach((line: any, index: number) => line.orderOfFinish = index + 1);
    return frame(renderScorecard({
      matchUp: dual,
      composition: compositions[compositionName],
      swapSides
    }));
  }
